-- GENERATED by `wfj generate` from data/gossip/gossip-77.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7700dbc07ef4547b"] = { "Pare che Skarr abbia trovato il suo prossimo sfidante! Non vorrei essere nei panni di quel povero sciocco!", "." },
  ["7705d302cc424b4f"] = { "Non rischierebbe di disfare la trama, se non viene ancorata a dovere prima di iniziare il lancio?", "." },
  ["7705d50c2f6971f5"] = { "Ah, errore mio, {name}. Ti chiedo scusa. Non mi ero accorto che possedessi la Torcia. Sono lieto di fare la tua conoscenza.\n\nMolti avventurieri arrivano fin qui in cerca di tesori perduti o attratti dalla promessa di creature mistiche da uccidere, solo per essere respinti da un santuario apparentemente vuoto. Ma noi conosciamo la verità, non è così, {name}?\n\nQuesto santuario cela un segreto più grande ai membri comuni dell'⟦Horde=Orda⟧. Per noi è sacro.", "." },
  ["77088fb2462aea8f"] = { "Se ti serve tempo per riposare e recuperare le forze, il posto migliore è la locanda di Dolanaar. Keldamyr, che la gestisce, si prenderà cura di te.", "." },
  ["770d83a4590d7402"] = { "Mi serve un altro ⟦Relic Bundle=Mucchio di Reliquie⟧!", "." },
  ["770ea11d794aa499"] = { "La ⟦Darkmoon Faire=Fiera di Lunacupa⟧ resterà aperta solo per poco, prima che cali il sipario. Non mancare di visitarla oggi!", "." },
  ["7713d9c9480713a7"] = { "Usa l'ingegneria per accedere a schemi nascosti!", "." },
  ["7715c8db9121babc"] = { "Su, Zeliek, non scacciarli. Non prima di esserci divertiti!", "." },
  ["7723dccfa9fcd4b9"] = { "Giri il corpo e vedi sull'orchessa morta i segni di lame e incantesimi: la sua armatura è quasi distrutta, i capelli incollati al viso.\n\nDalla descrizione che ne ha fatto Mankrik, non hai alcun dubbio che fosse sua moglie.\n\nLa notizia lo sconvolgerà, ma senti che deve conoscere la verità.", "." },
  ["77260b3feead6251"] = { "Mi dispiace, <fratello/sorella>, ma non venderò i miei raptor a chi non ha dimostrato di essere almeno Amichevole con la tribù ⟦Darkspear=Lanciascura⟧. Quando ti farai valere e ci dimostrerai di essere almeno Amichevole, allora i miei raptor saranno a tua disposizione.", "." },
  ["7726e70c9ac4be60"] = { "Scalporosso, Sabbiafurente, Fendicranio, Ramovile e Scorzasecca. Tutti giurano fedeltà a Jin, e le loro anime a Hakkar. Hai perso.", "." },
  ["772983d9ea7580b6"] = { "Mi interessa l'addestramento da stregone.", "." },
  ["772a3d65ac619a4b"] = { "Ho perso la mia ⟦Zandalar Haruspex's Tunic=Giubba dell'Aruspice degli Zandalari⟧, Maywiki. Ne hai una di ricambio?", "." },
  ["772d5039a8a49278"] = { "Dove dovrei cercare E'ko?", "." },
  ["772d90a4aa88c47d"] = { "La miscela è pronta, {name}. Ora dobbiamo salvare il piccolo.", "." },
  ["773221db61c86bf4"] = { "Via, a Grom'Gol, {name}!", "." },
  ["77324e6fd2d4674d"] = { "Io e mio fratello ci siamo votati a Sylvanas. È stata il nostro faro di luce nei tempi più bui. Ci sacrifichiamo ogni giorno perché la nostra gente superi il destino che ci ha scelti.\n\nNon resteremo deboli. Ci prenderemo ciò che ci è dovuto. Restituiremo dieci volte il dolore che ci è stato inflitto. E lo faremo con il sorriso sulle labbra.", "." },
  ["77351c6cd968a51a"] = { "Sorgete, miei soldati! Sorgete e combattete ancora una volta!", "." },
  ["77351c9328c20fea"] = { "Hai assaggiato il nostro pane? Il fornaio Masterson dev'essere il cuoco più dotato che sia mai esistito!", "." },
  ["77374398e2eea02d"] = { "Sta' in guardia... Arnak ha uno strano potere sui ⟦Grimtotem=Totem Truce⟧... non saranno felici di vedermi scappare.", "." },
  ["7739bfac3f5b9631"] = { "NON PUOI SCONFIGGERE LA FIAMMA VIVENTE! VENITE, SERVI DEL FUOCO! FATEVI AVANTI, CREATURE DELL'ODIO! IL VOSTRO PADRONE VI CHIAMA!", "." },
  ["77460b6c76ab179c"] = { "Mi chiamo Bilgewhizzle, e sono l'ingegnere capo della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧. In cosa posso esserti utile?", "." },
  ["774978a90b7a5caa"] = { "Qui finisce la corsa, per chi amico mio non è!", "." },
  ["774a10465a6cb8d9"] = { "Maledetto te, Halyndor! Ci hai condotti alla rovina!", "." },
  ["77672d8b2edf15c8"] = { "borbotta borbotta...", "." },
  ["7768b2f028e7a237"] = { "Noi paladini dobbiamo guadagnarci ogni giorno il nostro posto tra i nostri fratelli Reietti, per non essere giudicati dei fanatici come la ⟦Scarlet Crusade=Crociata Scarlatta⟧. La luce non è soltanto uno strumento dei nostri nemici, ma un canale per la nostra giusta furia! È nella devozione alla Dama Oscura e nell'amore per la nostra casa che possiamo incanalare la luce per portare giustizia ai nostri nemici.\n\nLa Regina Banshee ci tiene d'occhio. Che lo faccia pure. Vedrà che la nostra risolutezza non vacillerà mai. Noi siamo Reietti!", "." },
  ["7773ec127574d494"] = { "Farò del mio meglio per tradurre e descrivere ciò che vedo.", "." },
  ["77786960a07dbdf8"] = { "Che storia incredibile. E come è morto?", "." },
  ["77798fe85232ef04"] = { "Sparisci dalla mia vista, mortale. Basta la tua sola presenza a spingermi alla violenza.", "." },
  ["777e4a86e639a13b"] = { "Mostrate ai nemici la vostra risolutezza, soldati! Schiacciateli sotto i piedi! Sotto l'acciaio!", "." },
  ["777f6fbee5184b42"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ è stato conquistato dall'⟦Horde=Orda⟧!", "." },
  ["7780e28dfa2d3c41"] = { "E cerca di non perderti, stavolta....", "." },
  ["7786d83200b2e4c5"] = { "%s scappa via veloce dallo ⟦Umi's Mechanical Yeti=Yeti Meccanico di Umi⟧.", "." },
  ["778bfff0199c7878"] = { "Capitolo sulle Pezze Consumate dell'Abominio.", "." },
  ["778df2cc3f53c470"] = { "Mi chiedi dei Figli di Cenarius, Remulos e Zaetar.\n\nMio padre, Remulos, era forte e bello, e mio zio, Zaetar, molto astuto e di corporatura minuta. Benché fossero rispettati quasi allo stesso modo, Zaetar sentiva sempre di non poter eguagliare la gloria e le attenzioni che, secondo lui, spettavano a Remulos.\n\nDopo la nascita mia e delle mie sorelle, Zaetar, accecato dalla gelosia, si mise in testa di superare il fratello... Fu l'artefice della propria fine. La tristezza che mi dà non si è mai attenuata, nemmeno con il passare del tempo...", "." },
  ["779fde1907aa1f52"] = { "Ben combattuto, Narrisha. La prossima volta vi prendiamo, Squadra Rossa!", "." },
  ["77b00f24b14f2449"] = { "Sono troll, insegno sartoria, e questo è il mio saluto predefinito.", "." },
  ["77b1591306410d00"] = { "Tutti i membri dell'⟦Horde=Orda⟧ sono uguali ai miei occhi, {name}. Abbiamo sopportato tutti molti fardelli, e se non fosse per la saggezza e l'onore, non saremmo migliori del Flagello o del mio popolo quando il nostro sangue era contaminato dal demone Mannoroth.\n\nÈ tuo dovere aiutare l'⟦Horde=Orda⟧ e difendere il nostro modo di vivere. Ma è anche tuo dovere sapere quando concedere grazia e compassione, all'amico come al nemico.\n\nCerca di capirlo bene. Questa è la nuova ⟦Horde=Orda⟧, non un esercito generato dai demoni e privo di libero arbitrio.", "." },
  ["77b1fb92b96417b8"] = { "Smettila di fare il bambino, Razal'blade. È ora che inizi a comportarti come uno delle forze d'élite del Capoguerra. Non vuoi finire come Gargal, vero?", "." },
  ["77b3acaff9fd8786"] = { "Se hai sentito che tutte le raccolte dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧ sono state completate, allora hai sentito bene, {class}. Tutte le merci per la guerra che abbiamo raccolto e preparato vengono spedite alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e manca meno di un giorno all'arrivo delle ultime. Dopodiché, credo, non resterà che aspettare di vedere chi ricomporrà lo scettro con cui suonare il gong, che aprirà i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e annuncerà la guerra.", "." },
  ["77b7bdd21b4efd5b"] = { "Mi serve un Focalizzatore Vitreo.", "." },
  ["77ba83f9fd955605"] = { "Tratta bene la viverna mentre ti porta a destinazione. Che i tuoi antenati veglino su di te, {name}.", "." },
  ["77c6a27cf3cb6176"] = { "Le torri e i fortilizi della ⟦Alterac Valley=Valle d'Alterac⟧ sono posizioni strategiche vitali. Se controlliamo una torre, le nostre truppe possono tirare da lì a grandi distanze.", "." },
  ["77c7f7489e8d387e"] = { "%s ha un fortissimo capogiro!", "." },
  ["77cd23667f7cf0c2"] = { "Coccodè, coccodè, coccodè! Buona Veglia delle Ombre, {name}!", "." },
  ["77da5e890ac5999c"] = { "%s posa a terra la cassa di pezzi.", "." },
  ["77db0aa1677d93b6"] = { "Cosa si può fare in una locanda?\n\nBeh, quando ti fermi in una locanda, riposi comodissimo. Per questo raggiungerai lo stato di «Riposato» molto più in fretta che nelle terre selvagge. Quando sei nello stato di «Riposato», impari di più dall'esperienza.\n\nPuoi anche parlare con qualsiasi locandiere per ottenere una Pietra del Ritorno, e poi usare la Pietra del Ritorno per tornare rapidamente a quella locanda.", "." },
  ["77e31b446c7b5c6b"] = { "Vuoi combattere? E combattimento sia!", "." },
  ["77e32b417b922c9c"] = { "E cos'è successo?", "." },
  ["77e6d144a5214453"] = { "La forma corporea di Ragnaros deve essere distrutta. Dai suoi resti emergerà la sua essenza. In questo stato indebolito, la presa di Ragnaros sulla prigione di Thunderaan si allenta. L'essenza stessa fa da chiave...", "." },
  ["77e8c915ca25b77c"] = { "{name}, ho le informazioni che cerchi...", "." },
  ["77effe627ae0f9ed"] = { "Capitolo sul ⟦Frostwhisper's Embalming Fluid=Fluido per Imbalsamazioni di Soffiogelo⟧.", "." },
  ["77fcc04e2a64a90f"] = { "Cosa vuol dire «zug zug»?", "." },
})
